+    // rtmp1 = d ^ (b & (c ^ d)) = d ^ rtmp1
+    __ xorr(rtmp1, d, rtmp1);
+
+    m5_FF_GG_HH_II_epilogue_c(a, rtmp1);
+    m5_FF_GG_HH_II_epilogue_d(a, b, s);
@@ -5880,1 +5904,1 @@
